let lastAnnouncement = "";
function announce(message) {
  if (!message || message === lastAnnouncement) return;
  lastAnnouncement = message;
  tableStatus.textContent = message;
}

function showToast(message, kind = "info") {
  const stack = $("#toast-stack");
  if (!stack) return;
  const node = document.createElement("div");
  node.className = `toast toast-${kind}`;
  node.textContent = message;
  stack.appendChild(node);
  window.setTimeout(() => node.remove(), 4200);
}

function upsertTask(task) {
  if (!task?.id) return;
  const index = state.tasks.findIndex((item) => item.id === task.id);
  if (index >= 0) {
    const existing = state.tasks[index];
    const incomingAt = Number(task.updatedAt || 0);
    const existingAt = Number(existing.updatedAt || 0);
    if (incomingAt < existingAt) return;
    if (incomingAt === existingAt && task.status === "queued" && existing.status !== "queued") return;
    if (existing.status !== task.status && task.status === "completed") task._flashAt = Date.now();
    if (existing._enterAt) task._enterAt = existing._enterAt;
    if (existing._flashAt) task._flashAt = existing._flashAt;
    state.tasks[index] = task;
  } else {
    task._enterAt = Date.now();
    state.tasks.unshift(task);
  }
  scheduleRender("tasks");
  scheduleRender("stats");
}

async function syncTasks() {
  if (!hasAPI()) return;
  try {
    const tasks = await api().GetTasks();
    state.tasks = tasks || [];
    const known = new Set(state.tasks.map((task) => task.id));
    state.selected.forEach((id) => {
      if (!known.has(id)) state.selected.delete(id);
    });
    scheduleRender("tasks");
    scheduleRender("stats");
  } catch {
    // keep the current list; the event stream will catch up
  }
}

function removeTaskFromState(id) {
  state.tasks = state.tasks.filter((task) => task.id !== id);
  state.selected.delete(id);
  scheduleRender("tasks");
  scheduleRender("stats");
}

function taskMatchesFilter(task) {
  if (state.filter === "active") return task.status === "active";
  if (state.filter === "queued") return task.status === "queued" || task.status === "paused";
  if (state.filter === "done") return task.status === "completed";
  if (state.filter === "error") return task.status === "error";
  return true;
}

const fileCategories = [
  { key: "video", icon: "i-film", ext: /^(mp4|mkv|webm|avi|mov|m4v|flv|ts|mpeg|mpg)$/i },
  { key: "audio", icon: "i-music", ext: /^(mp3|m4a|flac|wav|ogg|opus|aac)$/i },
  { key: "archive", icon: "i-box", ext: /^(zip|rar|7z|tar|gz|bz2|xz|iso|dmg)$/i },
  { key: "program", icon: "i-app", ext: /^(exe|msi|apk|deb|rpm|appimage|pkg)$/i },
  { key: "other", icon: "i-doc", ext: /^(pdf|docx?|xlsx?|pptx?|txt|epub|json|csv)$/i }
];

function taskCategory(task) {
  const assigned = String(task.category || "");
  if (fileCategories.some((item) => item.key === assigned)) return assigned;
  const name = String(task.filePath || task.title || "").split(/[\\/]/).pop();
  const match = name.match(/\.([a-z0-9]{1,6})$/i);
  const ext = match ? match[1] : "";
  if (ext) {
    const found = fileCategories.find((item) => item.ext.test(ext));
    if (found) return found.key;
  }
  if (task.kind === "torrent") return "other";
  if (task.engine === "ytdlp") return task.quality === "audio" ? "audio" : "video";
  return "other";
}

function taskMatchesCategory(task) {
  return state.category === "all" || taskCategory(task) === state.category;
}

function categoryInfo(task) {
  const key = taskCategory(task);
  return fileCategories.find((item) => item.key === key) || fileCategories[fileCategories.length - 1];
}

function compareQueueOrder(a, b) {
  return (Number(b.priority) || 0) - (Number(a.priority) || 0)
    || (Number(a.createdAt) || 0) - (Number(b.createdAt) || 0)
    || String(a.id).localeCompare(String(b.id));
}

function queuedOrder() {
  return state.tasks
    .filter((task) => task.status === "queued")
    .slice()
    .sort(compareQueueOrder);
}

function queueRank(task) {
  if (task.status !== "queued") return 0;
  const index = queuedOrder().findIndex((item) => item.id === task.id);
  return index < 0 ? 0 : index + 1;
}

function canMoveQueue(task, direction) {
  const list = queuedOrder();
  const index = list.findIndex((item) => item.id === task.id);
  if (index < 0) return false;
  return direction === "up" ? index > 0 : index < list.length - 1;
}

function applyQueueOrder(tasks) {
  const byID = new Map((tasks || []).map((task) => [task.id, task]));
  state.tasks = state.tasks.map((task) => byID.get(task.id) || task);
  scheduleRender("tasks");
  scheduleRender("stats");
}

const normalizeText = (value) =>
  String(value || "")
    .replace(/[يى]/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/\u200c/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();

function taskMatchesQuery(task) {
  if (!state.query) return true;
  const haystack = normalizeText([task.title, task.source, task.url, task.filePath].join(" "));
  return haystack.includes(normalizeText(state.query));
}

function fileBadge(task) {
  if (task.kind === "torrent") return "TORRENT";
  const fromPath = task.filePath ? task.filePath.split(/[\\/]/).pop() : "";
  const fromURL = (() => {
    try { return new URL(task.url).pathname.split("/").pop(); } catch { return ""; }
  })();
  const name = fromPath || fromURL || "";
  const match = name.match(/\.([a-z0-9]{1,5})$/i);
  return match ? match[1].toUpperCase() : task.engine === "ytdlp" ? "VIDEO" : "FILE";
}

function statusInfo(status) {
  const map = {
    active: { key: "status.active", icon: "i-download" },
    queued: { key: "status.queued", icon: "i-refresh" },
    paused: { key: "status.paused", icon: "i-pause" },
    completed: { key: "status.completed", icon: "i-check" },
    error: { key: "status.error", icon: "i-alert" },
    canceled: { key: "status.canceled", icon: "i-close" }
  };
  return map[status] || map.queued;
}

function relativeTime(timestamp) {
  const ms = Number(timestamp) || 0;
  if (!ms) return "—";
  const diff = Date.now() - ms;
  if (diff < 60_000) return t("time.now");
  if (diff < 3_600_000) return t("time.minutes", { count: formatInteger(Math.floor(diff / 60_000)) });
  if (diff < 86_400_000) return t("time.hours", { count: formatInteger(Math.floor(diff / 3_600_000)) });
  const days = Math.floor(diff / 86_400_000);
  if (days < 7) return t("time.days", { count: formatInteger(days) });
  return t("time.date", { date: new Intl.DateTimeFormat(lang === "fa" ? "fa-IR" : "en-US", { month: "short", day: "numeric" }).format(new Date(ms)) });
}

function actionButton(action, id, label, icon) {
  return `<button type="button" class="row-action" data-action="${action}" data-id="${escapeHTML(id)}" aria-label="${escapeHTML(label)}" title="${escapeHTML(label)}"><svg class="icon" aria-hidden="true"><use href="#${icon}"></use></svg></button>`;
}

const errorCauses = [
  { key: "error.geo", test: /geo|country|region|not available in your/i },
  { key: "error.private", test: /private|members-only|login|sign in|requires authentication|video unavailable|removed|deleted/i },
  { key: "error.expired", test: /expired|http error 40[13]|forbidden|unauthorized|cookies|authentication/i },
  { key: "error.rate", test: /rate limit|too many requests|http error 429/i },
  { key: "error.disk", test: /no space|disk full|enospc|not enough space/i },
  { key: "error.ffmpeg", test: /ffmpeg|postprocess|merge|conversion/i },
  { key: "error.format", test: /requested format|format.*not available|no video formats|unsupported url|no formats/i },
  { key: "error.network", test: /timed out|timeout|connection|network|temporary failure|name or service|dns|unreachable|ssl|connection reset|broken pipe/i },
  { key: "error.engine", test: /aria2|rpc|daemon|engine|موتور دانلود/i }
];

function errorCause(task) {
  const message = String(task?.error || "");
  const cause = errorCauses.find((item) => item.test.test(message));
  return t(cause?.key || "error.unknown");
}

function rowMotionClass(task) {
  const now = Date.now();
  if (task._flashAt && now - task._flashAt < 1200) return " row-flash";
  if (task._enterAt && now - task._enterAt < 700) return " row-enter";
  return "";
}

function setText(el, value) {
  if (el && el.textContent !== value) el.textContent = value;
}

function progressParts(task) {
  const hasProgress = task.status === "active" || task.status === "queued" || task.status === "paused";
  const progress = Math.max(0, Math.min(100, Number(task.progress) || 0));
  return { hasProgress, progress, text: formatPercent(progress) };
}

function metricsList(task) {
  const { hasProgress } = progressParts(task);
  if (!hasProgress) return [];
  const metrics = [
    t("task.speed", { speed: formatMB(task.speed) }),
    t("task.eta", { time: formatETA(task.eta) })
  ];
  if (Number(task.connections) > 0) metrics.push(t("task.connections", { count: formatInteger(task.connections) }));
  return metrics;
}

function metricsMarkup(task) {
  const metrics = metricsList(task);
  return metrics.length ? `<div class="row-metrics">${metrics.map((item) => `<span>${escapeHTML(item)}</span>`).join("")}</div>` : "";
}

function sizeSubText(task) {
  const { hasProgress } = progressParts(task);
  if (!hasProgress || !(Number(task.total) > 0)) return "";
  return `${formatVolume(task.downloaded)} / ${formatSize(task.total)}`;
}

function rowSpeed(task) {
  if (task.status !== "active") return "—";
  return `${formatMB(task.speed)} MB/s`;
}

function rowEta(task) {
  if (task.status !== "active" || !(Number(task.eta) > 0)) return "—";
  return formatETA(task.eta);
}

function progressState(task) {
  const { progress } = progressParts(task);
  const total = Number(task.total) || 0;
  const done = Number(task.downloaded) || 0;
  const totalText = total ? formatSize(total) : "—";
  switch (task.status) {
    case "active":
      if (total <= 0) {
        return { progress: 0, left: `${formatVolume(done)} / ${totalText}`, right: "", tone: "st-active", indeterminate: true };
      }
      return { progress, left: `${formatVolume(done)} / ${totalText}`, right: formatPercent(progress), tone: "st-active" };
    case "paused":
      return { progress, left: `${formatVolume(done)} / ${totalText}`, right: t("status.paused"), tone: "st-paused" };
    case "queued":
      return { progress: 0, left: t("status.queued"), right: "", tone: "st-queued" };
    case "completed":
      return { progress: 100, left: totalText, right: t("status.completed"), tone: "st-completed" };
    case "error":
      return { progress, left: errorCause(task), right: t("status.error"), tone: "st-error" };
    case "canceled":
      return { progress, left: totalText, right: t("status.canceled"), tone: "st-canceled" };
    default:
      return { progress, left: totalText, right: formatPercent(progress), tone: "st-queued" };
  }
}

function rowMeta(task) {
  const size = formatSize(Number(task.total) || Number(task.downloaded) || 0);
  const source = String(task.source || task.engine || "").replace(/^https?:\/\//, "");
  const rank = queueRank(task);
  const queue = rank ? `${t("task.queueRank", { rank: formatInteger(rank) })} · ` : "";
  return source ? `${queue}${size} · ${source}` : `${queue}${size}`;
}

function rowHTML(task) {
  const info = statusInfo(task.status);
  const state = progressState(task);
  const category = categoryInfo(task);
  const barClass = state.indeterminate ? "bar is-indeterminate" : "bar";
  const progressNow = state.indeterminate ? "" : ` aria-valuenow="${Math.round(state.progress)}"`;
  const queued = task.status === "queued";
  const selected = isSelected(task.id);
  const queueUp = canMoveQueue(task, "up");
  const queueDown = canMoveQueue(task, "down");
  const actions = [];
  if (task.status === "active" || task.status === "queued") {
    actions.push(`<button type="button" class="ib" data-action="pause" data-id="${escapeHTML(task.id)}" aria-label="${escapeHTML(t("task.pause"))}" title="${escapeHTML(t("task.pause"))}"><svg class="icon" aria-hidden="true"><use href="#i-pause"></use></svg></button>`);
  } else if (task.status === "paused") {
    actions.push(`<button type="button" class="ib ib-primary" data-action="resume" data-id="${escapeHTML(task.id)}" aria-label="${escapeHTML(t("task.resume"))}" title="${escapeHTML(t("task.resume"))}"><svg class="icon" aria-hidden="true"><use href="#i-play"></use></svg></button>`);
  } else if (task.status === "error") {
    actions.push(`<button type="button" class="ib ib-danger" data-action="resume" data-id="${escapeHTML(task.id)}" aria-label="${escapeHTML(t("task.retry"))}" title="${escapeHTML(t("task.retry"))}"><svg class="icon" aria-hidden="true"><use href="#i-refresh"></use></svg></button>`);
  } else if (task.status === "completed") {
    actions.push(`<button type="button" class="ib" data-action="open" data-id="${escapeHTML(task.id)}" aria-label="${escapeHTML(t("task.open"))}" title="${escapeHTML(t("task.open"))}"><svg class="icon" aria-hidden="true"><use href="#i-check"></use></svg></button>`);
  }
  actions.push(`<button type="button" class="ib" data-action="folder" data-id="${escapeHTML(task.id)}" aria-label="${escapeHTML(t("app.openFolder"))}" title="${escapeHTML(t("app.openFolder"))}"><svg class="icon" aria-hidden="true"><use href="#i-folder"></use></svg></button>`);
  actions.push(`<details class="row-menu">
    <summary class="ib" aria-label="${escapeHTML(t("task.more"))}" title="${escapeHTML(t("task.more"))}"><svg class="icon" aria-hidden="true"><use href="#i-more"></use></svg></summary>
    <div class="menu-panel">
      ${queued ? `<button type="button" class="menu-item" data-action="queue-up" data-id="${escapeHTML(task.id)}"${queueUp ? "" : " disabled"}>${escapeHTML(t("task.queueUp"))}</button>` : ""}
      ${queued ? `<button type="button" class="menu-item" data-action="queue-down" data-id="${escapeHTML(task.id)}"${queueDown ? "" : " disabled"}>${escapeHTML(t("task.queueDown"))}</button>` : ""}
      <button type="button" class="menu-item" data-action="details" data-id="${escapeHTML(task.id)}">${escapeHTML(t("task.details"))}</button>
      ${task.status === "completed" ? `<button type="button" class="menu-item" data-action="verify" data-id="${escapeHTML(task.id)}">${escapeHTML(t("task.verify"))}</button>` : ""}
      <button type="button" class="menu-item" data-action="copy" data-id="${escapeHTML(task.id)}">${escapeHTML(t("task.copyLink"))}</button>
      <button type="button" class="menu-item menu-item-danger" data-action="remove" data-id="${escapeHTML(task.id)}">${escapeHTML(t("task.remove"))}</button>
      <button type="button" class="menu-item menu-item-danger" data-action="remove-file" data-id="${escapeHTML(task.id)}">${escapeHTML(t("task.removeFile"))}</button>
    </div>
  </details>`);
  return `<div class="row ${rowMotionClass(task).trim()}${selected ? " is-selected" : ""}" data-id="${escapeHTML(task.id)}" data-status="${escapeHTML(task.status)}">
    <div class="cell-file">
      <label class="row-check"><input type="checkbox" data-select="${escapeHTML(task.id)}" aria-label="${escapeHTML(t("bulk.selectOne", { name: task.title || task.url }))}"${selected ? " checked" : ""}></label>
      <span class="ic cat-${category.key}" aria-hidden="true"><svg class="icon"><use href="#${category.icon}"></use></svg></span>
      <span class="file-text">
        <span class="nm" title="${escapeHTML(task.title || task.url)}">${escapeHTML(task.title || task.url)}</span>
        <span class="mt">${escapeHTML(rowMeta(task))}</span>
      </span>
    </div>
    <div class="cell-progress">
      <div class="${barClass}" role="progressbar" aria-label="${escapeHTML(task.title)}" aria-valuemin="0" aria-valuemax="100"${progressNow}><i style="width:${state.progress}%"></i></div>
      <div class="pr"><span class="pr-left">${escapeHTML(state.left)}</span><span class="pr-right st ${state.tone}">${escapeHTML(state.right)}</span></div>
    </div>
    <div class="cell-speed sp">${escapeHTML(rowSpeed(task))}</div>
    <div class="cell-eta sp">${escapeHTML(rowEta(task))}</div>
    <div class="cell-actions acts">${actions.join("")}</div>
  </div>`;
}

function rowKey(task) {
  const note = task.status === "error" ? String(task.error || "") : "";
  return [task.id, task.status, task.title, task.url, task.source, task.total, task.category, task.priority, note].join("\u0001");
}

function patchRow(task) {
  const row = downloadsBody.querySelector(`.row[data-id="${task.id}"]`);
  if (!row) return;
  if (row.dataset.status !== String(task.status)) {
    const template = document.createElement("template");
    template.innerHTML = rowHTML(task);
    const fresh = template.content.firstElementChild;
    if (fresh) row.replaceWith(fresh);
    return;
  }
  const state = progressState(task);
  const bar = row.querySelector(".bar > i");
  if (bar) {
    const width = `${state.progress}%`;
    if (bar.style.width !== width) bar.style.width = width;
  }
  const wrap = row.querySelector(".bar");
  if (wrap) {
    const indeterminate = Boolean(state.indeterminate);
    wrap.classList.toggle("is-indeterminate", indeterminate);
    if (indeterminate) {
      wrap.removeAttribute("aria-valuenow");
    } else {
      const value = String(Math.round(state.progress));
      if (wrap.getAttribute("aria-valuenow") !== value) wrap.setAttribute("aria-valuenow", value);
    }
  }
  setText(row.querySelector(".pr-left"), state.left);
  setText(row.querySelector(".pr-right"), state.right);
  setText(row.querySelector(".cell-speed"), rowSpeed(task));
  setText(row.querySelector(".cell-eta"), rowEta(task));
  setText(row.querySelector(".mt"), rowMeta(task));
  const motion = rowMotionClass(task);
  row.classList.toggle("row-enter", motion.includes("row-enter"));
  row.classList.toggle("row-flash", motion.includes("row-flash"));
}

function visibleTaskList() {
  const list = state.tasks.filter(
    (task) => taskMatchesFilter(task) && taskMatchesCategory(task) && taskMatchesQuery(task)
  );
  if (state.sort === "name") {
    list.sort((a, b) => String(a.title || a.url).localeCompare(String(b.title || b.url), lang === "fa" ? "fa" : "en"));
  } else if (state.sort === "size") {
    list.sort((a, b) => (Number(b.total) || 0) - (Number(a.total) || 0));
  } else if (state.filter === "queued") {
    list.sort((a, b) => {
      if (a.status !== b.status) return a.status === "queued" ? -1 : 1;
      if (a.status === "queued") return compareQueueOrder(a, b);
      return (Number(b.createdAt) || 0) - (Number(a.createdAt) || 0);
    });
  } else {
    list.sort((a, b) => (Number(b.createdAt) || 0) - (Number(a.createdAt) || 0));
  }
  return list;
}

const renderQueue = { tasks: false, stats: false, frame: 0 };

function scheduleRender(kind) {
  renderQueue[kind] = true;
  if (renderQueue.frame) return;
  renderQueue.frame = requestAnimationFrame(() => {
    renderQueue.frame = 0;
    const tasks = renderQueue.tasks;
    const stats = renderQueue.stats;
    renderQueue.tasks = false;
    renderQueue.stats = false;
    if (tasks) renderTasks();
    if (stats) renderStats();
  });
}

function isSelected(id) {
  return state.selected.has(id);
}

function selectedTasks() {
  const byID = new Map(state.tasks.map((task) => [task.id, task]));
  return Array.from(state.selected).map((id) => byID.get(id)).filter(Boolean);
}

function clearSelection() {
  state.selected.clear();
  renderSelectionUI();
}

function setVisibleSelected(select) {
  visibleTaskList().forEach((task) => {
    if (select) state.selected.add(task.id);
    else state.selected.delete(task.id);
  });
  renderSelectionUI();
}

function renderSelectionUI() {
  const visible = visibleTaskList();
  const selectedVisible = visible.filter((task) => state.selected.has(task.id));
  const allVisible = visible.length > 0 && selectedVisible.length === visible.length;
  if (selectAll) {
    selectAll.checked = allVisible;
    selectAll.indeterminate = selectedVisible.length > 0 && !allVisible;
    selectAll.disabled = visible.length === 0;
  }
  if (selectAllToggle) {
    selectAllToggle.disabled = visible.length === 0;
    selectAllToggle.classList.toggle("is-active", allVisible);
    selectAllToggle.setAttribute("aria-pressed", String(allVisible));
  }
  downloadsBody.querySelectorAll("[data-select]").forEach((box) => {
    const checked = state.selected.has(box.dataset.select);
    box.checked = checked;
    box.closest(".row")?.classList.toggle("is-selected", checked);
  });
  if (!bulkBar) return;
  const tasks = selectedTasks();
  bulkBar.hidden = tasks.length === 0;
  setText(bulkCount, formatInteger(tasks.length));
  const pause = bulkBar.querySelector('[data-bulk="pause"]');
  const resume = bulkBar.querySelector('[data-bulk="resume"]');
  if (pause) pause.disabled = !tasks.some((task) => task.status === "active" || task.status === "queued");
  if (resume) resume.disabled = !tasks.some((task) => task.status === "paused" || task.status === "error");
}

async function bulkAction(action) {
  const tasks = selectedTasks();
  if (!tasks.length) return;
  if (action === "clear") {
    clearSelection();
    return;
  }
  try {
    if (action === "delete" || action === "delete-file") {
      const count = formatInteger(tasks.length);
      const key = action === "delete-file" ? "bulk.confirmDeleteFile" : "bulk.confirmDelete";
      if (!window.confirm(t(key, { count }))) return;
      await api().DeleteTasks(tasks.map((task) => task.id), action === "delete-file");
      tasks.forEach((task) => removeTaskFromState(task.id));
      state.selected.clear();
      showToast(t(action === "delete-file" ? "toast.removedFile" : "toast.removed", { count }), "success");
      return;
    }
    const eligible = tasks.filter((task) =>
      action === "pause"
        ? task.status === "active" || task.status === "queued"
        : task.status === "paused" || task.status === "error"
    );
    if (!eligible.length) return;
    await Promise.all(eligible.map((task) =>
      action === "pause" ? api().PauseTask(task.id) : api().ResumeTask(task.id)
    ));
    showToast(t("toast.bulkUpdated", { count: formatInteger(eligible.length) }), "success");
  } catch (error) {
    showToast(`${t("toast.actionError")} ${error?.message || error || ""}`.trim(), "error");
  } finally {
    await syncTasks();
    renderSelectionUI();
  }
}

async function resumeAll() {
  if (!hasAPI()) return;
  const tasks = state.tasks.filter((task) => task.status === "paused" || task.status === "error");
  if (!tasks.length) return;
  try {
    await Promise.all(tasks.map((task) => api().ResumeTask(task.id)));
    showToast(t("toast.resumedAll"));
    await syncTasks();
  } catch (error) {
    showToast(`${t("toast.actionError")} ${error?.message || error || ""}`.trim(), "error");
  }
}

function renderTasks() {
  const known = new Set(state.tasks.map((task) => task.id));
  state.selected.forEach((id) => {
    if (!known.has(id)) state.selected.delete(id);
  });
  renderSelectionUI();
  const visible = visibleTaskList();
  if (!state.booted) {
    downloadsBody.innerHTML = "";
    state.visibleCount = 0;
    downloadsTable.hidden = true;
    tablePanel.hidden = false;
    stateLoading.hidden = false;
    stateEmpty.hidden = true;
    stateError.hidden = true;
    return;
  }
  if (visible.length === 0) {
    const prev = state.visibleCount || 0;
    downloadsBody.innerHTML = "";
    state.visibleCount = 0;
    downloadsTable.hidden = true;
    tablePanel.hidden = false;
    stateLoading.hidden = true;
    stateError.hidden = true;
    stateEmpty.hidden = false;
    const isFiltered = state.filter !== "all" || state.query !== "" || state.category !== "all";
    emptyTitle.textContent = t(isFiltered ? "state.filterTitle" : "state.emptyTitle");
    emptyText.textContent = t(isFiltered ? "state.filterText" : "state.emptyText");
    emptyAction.textContent = t(isFiltered ? "state.clearFilters" : "action.newDownload");
    emptyAction.dataset.action = isFiltered ? "clear" : "new";
    if (prev !== 0) announce(emptyTitle.textContent);
    return;
  }
  tablePanel.hidden = true;
  stateLoading.hidden = true;
  stateEmpty.hidden = true;
  stateError.hidden = true;
  downloadsTable.hidden = false;
  const key = visible.map(rowKey).join("\n");
  if (downloadsBody.dataset.renderKey === key) {
    visible.forEach((task) => patchRow(task));
  } else {
    downloadsBody.dataset.renderKey = key;
    downloadsBody.innerHTML = visible.map(rowHTML).join("");
  }
  if (state.visibleCount !== visible.length) {
    state.visibleCount = visible.length;
    announce(t("announce.results", { count: formatInteger(visible.length) }));
  }
}

function renderCounts() {
  const tasks = state.tasks || [];
  const count = (test) => tasks.filter(test).length;
  setText($("#count-all"), String(tasks.length));
  setText($("#count-active"), String(count((task) => task.status === "active")));
  setText($("#count-queued"), String(count((task) => task.status === "queued" || task.status === "paused")));
  setText($("#count-done"), String(count((task) => task.status === "completed")));
  setText($("#count-error"), String(count((task) => task.status === "error")));
  ["video", "audio", "archive", "program", "other"].forEach((key) => {
    setText($(`#count-${key}`), String(count((task) => taskCategory(task) === key)));
  });
  if (pauseAllButton) {
    pauseAllButton.disabled = !tasks.some((task) => task.status === "active" || task.status === "queued");
  }
  if (resumeAllButton) {
    resumeAllButton.disabled = !tasks.some((task) => task.status === "paused" || task.status === "error");
  }
}

function formatVolume(bytes) {
  return Number(bytes) > 0 ? formatSize(bytes) : formatNumber(0);
}

function pushSpeedSample(value) {
  state.liveSpeeds.push(Math.max(0, Number(value) || 0));
  if (state.liveSpeeds.length > 30) state.liveSpeeds.shift();
  renderLiveTrace();
}

function renderLiveTrace() {
  const path = $("#live-trace-line");
  if (!path) return;
  const samples = state.liveSpeeds.length ? state.liveSpeeds : [0, 0];
  const max = Math.max(1, ...samples);
  const step = 100 / Math.max(1, samples.length - 1);
  const points = samples.map((value, index) => {
    const x = (index * step).toFixed(2);
    const y = (30 - Math.min(30, (value / max) * 27) - 1.5).toFixed(2);
    return `${x} ${y}`;
  });
  const line = `M${points.join(" L")}`;
  path.setAttribute("d", line);
  const area = $("#live-trace-area");
  if (area) area.setAttribute("d", `${line} L100 30 L0 30 Z`);
}

function renderConnectionStatus() {
  const online = navigator.onLine !== false;
  if (connectionStatus) {
    connectionStatus.textContent = t(online ? "net.online" : "net.offline");
    connectionStatus.classList.toggle("is-offline", !online);
  }
  const quickInternet = $("#quick-internet");
  if (quickInternet) {
    quickInternet.textContent = t(online ? "net.online" : "net.offline");
    quickInternet.classList.toggle("is-offline", !online);
  }
}

function renderStats() {
  const st = state.stats || {};
  setText($("#stat-speed"), formatMB(st.speed));
  setText(statActive, formatInteger(st.active || 0));
  setText(statSlots, formatInteger((state.settings && state.settings.maxConcurrent) || 2));
  const today = formatSizeParts(st.dailyBytes || 0);
  setText(statToday, today.value);
  setText(statTodayUnit, today.unit);
  renderLiveTrace();
  renderChartQuick();
  renderCounts();

  const total = Number(st.diskTotal) || 0;
  const free = Number(st.diskFree) || 0;
  const used = Number(st.diskUsed) || 0;
  const percent = total > 0 ? Math.min(100, Math.max(0, (used / total) * 100)) : 0;
  if (storeBar) storeBar.style.width = `${percent}%`;
  setText(storePercent, formatPercent(percent));
  if (storeFree) {
    storeFree.textContent = total
      ? t("storage.freeText", { free: `${formatGB(free)} ${t("unit.gb")}`, total: `${formatGB(total)} ${t("unit.gb")}` })
      : "—";
  }
}

function dateParts(value) {
  const date = new Date(`${value}T12:00:00`);
  if (Number.isNaN(date.getTime())) return { short: value, full: value };
  const locale = lang === "fa" ? "fa-IR" : "en-US";
  return {
    short: new Intl.DateTimeFormat(locale, { weekday: "short" }).format(date),
    full: new Intl.DateTimeFormat(locale, { weekday: "long", month: "short", day: "numeric" }).format(date)
  };
}

function chartScaleMax(peakBytes) {
  const peakMB = Math.max(0, Number(peakBytes) || 0) / (1024 * 1024);
  if (peakMB <= 0) return 20;
  const steps = [2, 5, 10, 20, 30, 40, 50, 75, 100, 150, 200, 300, 500, 750, 1000];
  return steps.find((step) => peakMB <= step) || Math.ceil(peakMB / 500) * 500;
}

function renderChart() {
  if (!speedBars || !speedDays) return;
  const points = Array.isArray(state.speedHistory) ? state.speedHistory.slice(-7) : [];
  const speeds = points.map((point) => Math.max(0, Number(point.speed) || 0));
  const peak = speeds.length ? Math.max(...speeds) : 0;
  const peakIndex = peak > 0 ? speeds.indexOf(peak) : -1;
  const scaleMax = chartScaleMax(peak);
  const empty = !points.length || peak <= 0;
  setText(speedTitle, t(state.chartPeriod === "last" ? "chart.titleLast" : "chart.titleWeek"));
  $$(".speed-y span").forEach((node, index) => {
    setText(node, formatNumber(Math.round(scaleMax * (1 - index / 4) * 10) / 10));
  });
  speedBars.innerHTML = empty ? "" : points.map((point, index) => {
    const speed = speeds[index];
    const height = scaleMax > 0 ? Math.min(100, (speed / (1024 * 1024)) / scaleMax * 100) : 0;
    const peakClass = index === peakIndex ? " is-peak" : "";
    const day = dateParts(point.day).full;
    return `<div class="speed-slot"><span class="speed-bar${peakClass}" style="height:${height.toFixed(2)}%" title="${escapeHTML(`${day} · ${formatMB(speed)} ${t("unit.mbps")}`)}"></span></div>`;
  }).join("");
  speedDays.innerHTML = points.map((point) => {
    const day = dateParts(point.day);
    return `<span class="speed-day"><span class="day-full">${escapeHTML(day.full)}</span><span class="day-short">${escapeHTML(day.short)}</span></span>`;
  }).join("");
  if (speedEmpty) speedEmpty.hidden = !empty;
  if (peak > 0 && peakIndex >= 0) {
    setText(speedPeak, `${formatMB(peak)} ${t("unit.mbps")}`);
    setText(speedPeakDay, dateParts(points[peakIndex].day).full);
  } else {
    setText(speedPeak, "—");
    setText(speedPeakDay, "");
  }
  let caption = "";
  if (!empty && points.length) {
    caption = t("chart.caption", {
      start: dateParts(points[0].day).full,
      end: dateParts(points[points.length - 1].day).full,
      peak: formatMB(peak),
      day: dateParts(points[peakIndex].day).full
    });
  }
  setText(speedCaption, caption);
  if (speedPlot) speedPlot.setAttribute("aria-label", caption || t("chart.empty"));
  $$(".speed-period").forEach((button) => {
    const active = button.dataset.period === state.chartPeriod;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  renderChartQuick();
}

function renderChartQuick() {
  const st = state.stats || {};
  setText($("#quick-active"), formatInteger(st.active || 0));
  setText($("#quick-completed"), formatInteger(st.completed || 0));
  setText($("#quick-volume"), formatSize(st.completedBytes || 0));
  setText($("#quick-daily"), formatSize(st.dailyBytes || 0));
  setText($("#quick-monthly"), formatSize(st.monthlyBytes || 0));
  setText($("#quick-avg"), Number(st.avgSpeed) > 0 ? `${formatMB(st.avgSpeed)} ${t("unit.mbps")}` : "—");
  setText($("#quick-peak"), Number(st.peakSpeed) > 0 ? `${formatMB(st.peakSpeed)} ${t("unit.mbps")}` : "—");
}

async function selectChartPeriod(period) {
  const next = period === "last" ? "last" : "week";
  state.chartPeriod = next;
  if (hasAPI()) {
    try {
      state.speedHistory = await api().GetSpeedHistory(next);
    } catch {
      state.speedHistory = [];
    }
  }
  renderChart();
}

async function refreshTools() {
  if (!hasAPI()) return;
  try {
    const tools = await api().GetToolsStatus();
    if (tools) {
      state.tools = tools;
      renderTools();
    }
  } catch (error) {
    return;
  }
}

function renderTools() {
  const tools = state.tools || {};
  const text = tools.ready ? t("settings.toolsReady") : tools.aria2 || tools.ytdlp ? t("settings.toolsPartial") : t("settings.toolsMissing");
  const node = $("#tools-status");
  if (node) node.textContent = text;
  let label = t("app.ready");
  let warn = false;
  if (!tools.ready) {
    label = tools.aria2 || tools.ytdlp ? t("app.partial") : t("app.missing");
    warn = true;
  }
  if (pageSub) {
    pageSub.textContent = label;
    pageSub.classList.toggle("is-warn", warn);
  }
}

function renderAll() {
  renderTasks();
  renderStats();
  renderChart();
  renderTools();
}

function applyLanguage(nextLang) {
  lang = nextLang === "en" ? "en" : "fa";
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === "fa" ? "rtl" : "ltr";
  document.title = t("meta.title");
  metaDescription.setAttribute("content", t("meta.description"));
  $$("[data-i18n]").forEach((element) => { element.textContent = t(element.dataset.i18n); });
  $$("[data-i18n-placeholder]").forEach((element) => { element.placeholder = t(element.dataset.i18nPlaceholder); });
  $$("[data-i18n-aria-label]").forEach((element) => { element.setAttribute("aria-label", t(element.dataset.i18nAriaLabel)); });
  $$("[data-label-key]").forEach((element) => { element.dataset.label = t(element.dataset.labelKey); });
  updatePreferenceControls();
  renderConnectionStatus();
  renderAll();
  updateSortLabel();
}

function applyTheme() {
  if (!palettes[palette]) palette = "ember";
  document.documentElement.dataset.theme = theme;
  document.documentElement.dataset.palette = palette;
  metaThemeColor.setAttribute("content", palettes[palette]?.bg[theme] || palettes.ember.bg[theme]);
  applyAccent(accent);
  updatePreferenceControls();
}

function updatePreferenceControls() {
  const isDark = theme === "dark";
  themeToggle.setAttribute("aria-label", t(isDark ? "theme.toLight" : "theme.toDark"));
  themeToggle.title = t(isDark ? "theme.toLight" : "theme.toDark");
  languageToggle.setAttribute("aria-label", t(lang === "fa" ? "lang.switchToEn" : "lang.switchToFa"));
  languageToggle.title = t(lang === "fa" ? "lang.switchToEn" : "lang.switchToFa");
  languageCode.textContent = lang === "fa" ? "EN" : "FA";
  $$(".theme-option").forEach((button) => {
    const active = button.dataset.themeChoice === theme;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  renderPaletteOptions();
}

function setFilter(filter) {
  state.filter = filter;
  $$(".filter").forEach((button) => {
    const active = button.dataset.filter === filter;
    button.classList.toggle("is-active", active);
    if (button.hasAttribute("aria-pressed")) button.setAttribute("aria-pressed", String(active));
  });
  $$(".side-link[data-filter]").forEach((button) => {
    button.classList.toggle("is-active", button.dataset.filter === filter);
  });
  renderTasks();
}

function setCategory(category) {
  state.category = category;
  state.filter = "all";
  $$(".side-link[data-category]").forEach((button) => {
    button.classList.toggle("is-active", button.dataset.category === category);
  });
  setFilter("all");
  renderTasks();
}

function updateSortLabel() {
  if (!sortToggle) return;
  sortToggle.textContent = t(`sort.${state.sort}`);
}

function cycleSort() {
  const order = ["recent", "name", "size"];
  state.sort = order[(order.indexOf(state.sort) + 1) % order.length];
  storage.set("dm-sort", state.sort);
  updateSortLabel();
  renderTasks();
}

async function pauseAll() {
  if (!hasAPI()) return;
  const running = state.tasks.filter((task) => task.status === "active" || task.status === "queued");
  if (!running.length) return;
  try {
    await Promise.all(running.map((task) => api().PauseTask(task.id)));
    showToast(t("toast.pausedAll"));
  } catch (error) {
    showToast(`${t("toast.actionError")} ${error?.message || error || ""}`.trim(), "error");
  }
}

function resetFilters() {
  state.query = "";
  searchInput.value = "";
  state.category = "all";
  $$(".side-link[data-category]").forEach((button) => button.classList.remove("is-active"));
  setFilter("all");
  renderTasks();
  downloadsTitle.setAttribute("tabindex", "-1");
  downloadsTitle.focus({ preventScroll: true });
}

function openDialog(dialog) {
  if (!dialog || dialog.open) return;
  dialog.showModal();
  document.body.classList.add("dialog-open");
}

function closeDialog(dialog) {
  if (dialog?.open) dialog.close();
}

function openDownloadDialog(prefill = "") {
  if (!hasAPI()) {
    showToast(t("app.bootError"), "error");
    return;
  }
  urlError.hidden = true;
  feedback.hidden = true;
  urlInput.removeAttribute("aria-invalid");
  if (prefill) urlInput.value = prefill;
  syncDownloadFields();
  openDialog(downloadDialog);
  window.setTimeout(() => urlInput.focus(), 30);
}

function renderBridgeInfo(info) {
  state.bridge = info || {};
  const enabled = info?.enabled === undefined
    ? state.settings?.browserBridgeEnabled !== false
    : Boolean(info.enabled);
  const running = Boolean(info?.running);
  const error = String(info?.error || "").trim();
  let status = "stopped";
  let key = "settings.bridgeStopped";
  if (!enabled) {
    status = "stopped";
  } else if (running) {
    status = "running";
    key = "settings.bridgeRunning";
  } else if (error) {
    status = "error";
    key = "settings.bridgeError";
  }
  bridgeStatus.dataset.state = status;
  bridgeStatusText.textContent = t(key);
  bridgeError.textContent = error;
  bridgeError.hidden = !error;
}

async function refreshBridgeInfo() {
  if (!hasAPI()) return;
  try {
    renderBridgeInfo(await api().GetBridgeInfo());
  } catch (error) {
    renderBridgeInfo({ enabled: true, running: false, error: String(error?.message || error || "") });
  }
}

async function copyBridgeToken() {
  const token = $("#settings-bridge-token").value.trim();
  if (!token) return;
  if (await copyText(token)) showToast(t("settings.bridgeCopied"), "success");
  else showToast(t("task.copyError"), "error");
}

async function openExtensionFolder() {
  try {
    await api().OpenExtensionFolder();
  } catch (error) {
    showToast(`${t("settings.extensionError")} ${error?.message || error || ""}`.trim(), "error");
  }
}

function openSettingsDialog() {
  if (!hasAPI()) return;
  const s = state.settings || {};
  $("#settings-folder").value = s.downloadDir || "";
  $("#settings-concurrent").value = s.maxConcurrent || 2;
  $("#settings-connections").value = s.connections || 8;
  $("#settings-proxy").value = s.proxy || "";
  $("#settings-schedule").checked = Boolean(s.scheduleEnabled);
  $("#settings-schedule-start").value = s.scheduleStart || "";
  $("#settings-schedule-stop").value = s.scheduleStop || "";
  $("#settings-shutdown").checked = Boolean(s.shutdownOnComplete);
  $("#settings-autoretry").checked = s.autoRetry !== false;
  syncScheduleFields();
  $("#settings-accent").value = accent || paletteAccent();
  renderPaletteOptions();
  $("#settings-token").value = s.githubToken || "";
  $("#settings-notify").checked = s.notifyOnComplete !== false;
  $("#settings-bridge").checked = s.browserBridgeEnabled !== false;
  $("#settings-bridge-token").value = s.browserToken || "";
  $("#settings-clipboard").checked = Boolean(s.clipboardWatch);
  $("#settings-auto-clipboard").checked = Boolean(s.autoAddClipboard);
  $("#settings-autostart").checked = Boolean(s.autoStart);
  settingsFeedback.hidden = true;
  renderTools();
  refreshTools();
  renderBridgeInfo(state.bridge);
  refreshBridgeInfo();
  openDialog(settingsDialog);
}

async function openGitHubDialog() {
  if (!hasAPI()) return;
  githubFeedback.hidden = true;
  if (!githubResults.children.length) {
    githubResults.innerHTML = `<p class="github-hint">${escapeHTML(t("github.hint"))}</p>`;
  }
  openDialog(githubDialog);
  $("#github-query").focus();
}

function validateDownloadURL(value) {
  if (/^magnet:\?/i.test(value)) return true;
  try {
    const parsed = new URL(value);
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
}

function selectedEngine() {
  const value = downloadEngine.value;
  if (value === "torrent") return "aria2";
  if (value === "ytdlp") return "ytdlp";
  if (value === "aria2") return "aria2";
  return "auto";
}

function syncDownloadFields() {
  const engine = downloadEngine.value;
  const isTorrent = engine === "torrent" || /^magnet:/i.test(urlInput.value.trim());
  const isDirect = engine === "aria2";
  const useMedia = !isTorrent && !isDirect;
  [downloadQuality, downloadContainer, downloadSubtitles, downloadPlaylist].forEach((element) => {
    if (element) element.disabled = !useMedia;
  });
  if (!useMedia) {
    downloadQuality.value = "best";
    downloadContainer.value = "mp4";
    downloadSubtitles.checked = false;
    downloadPlaylist.checked = false;
    return;
  }
  const mp4 = downloadContainer.value === "mp4";
  Array.from(downloadQuality.options).forEach((option) => {
    const high = option.value === "1440" || option.value === "2160";
    option.disabled = mp4 && high;
  });
  if (mp4 && (downloadQuality.value === "1440" || downloadQuality.value === "2160")) {
    downloadQuality.value = "best";
  }
}

async function submitDownload(event) {
  event.preventDefault();
  const value = urlInput.value.trim();
  if (!validateDownloadURL(value)) {
    feedback.hidden = true;
    urlError.hidden = false;
    urlInput.setAttribute("aria-invalid", "true");
    urlInput.focus();
    return;
  }
  urlError.hidden = true;
  urlInput.removeAttribute("aria-invalid");
  downloadSubmit.disabled = true;
  downloadSubmit.textContent = t("dialog.adding");
  feedback.hidden = true;
  try {
    const useMedia = !downloadQuality.disabled;
    const payload = {
      url: value,
      engine: selectedEngine(),
      category: downloadCategory.value,
      quality: useMedia ? downloadQuality.value : "best",
      container: useMedia ? downloadContainer.value : "",
      subtitles: useMedia ? downloadSubtitles.checked : false,
      playlist: useMedia ? downloadPlaylist.checked : false,
      username: downloadUsername.value.trim(),
      password: downloadPassword.value,
      cookies: downloadCookies.value.trim()
    };
    let result = await api().AddDownloadChecked(payload);
    if (result.duplicate) {
      if (!window.confirm(t("dialog.duplicate"))) {
        feedback.textContent = t("dialog.duplicateKept");
        feedback.hidden = false;
        return;
      }
      result = await api().AddDownloadChecked({ ...payload, allowDuplicate: true });
    }
    const task = result.task;
    upsertTask(task);
    setFilter("all");
    closeDialog(downloadDialog);
    downloadForm.reset();
    downloadEngine.value = "auto";
    downloadCategory.value = "";
    downloadContainer.value = "mp4";
    syncDownloadFields();
    showToast(t("dialog.added"), "success");
    downloadsTitle.setAttribute("tabindex", "-1");
    downloadsTitle.focus({ preventScroll: true });
  } catch (error) {
    feedback.textContent = `${t("dialog.startError")} ${error?.message || error || ""}`.trim();
    feedback.hidden = false;
    downloadSubmit.disabled = false;
    downloadSubmit.textContent = t("dialog.submit");
  } finally {
    downloadSubmit.disabled = false;
    downloadSubmit.textContent = t("dialog.submit");
  }
}

async function copyText(value) {
  try {
    await navigator.clipboard.writeText(value);
    return true;
  } catch {
    const area = document.createElement("textarea");
    area.value = value;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    const copied = document.execCommand("copy");
    area.remove();
    return copied;
  }
}

function detailsItem(label, value, mono = false) {
  return `<div class="details-item"><span>${escapeHTML(label)}</span><strong class="${mono ? "mono" : ""}" ${mono ? 'dir="ltr"' : ""}>${escapeHTML(value || t("details.empty"))}</strong></div>`;
}

function renderTaskDetails(task) {
  const health = Number(task.total) > 0 && Number(task.downloaded) === Number(task.total)
    ? t("details.healthy")
    : t("details.incomplete");
  detailsBody.innerHTML = `
    <p class="details-title">${escapeHTML(task.title || task.url)}</p>
    <div class="details-grid">
      ${detailsItem(t("details.status"), t(statusInfo(task.status).key))}
      ${detailsItem(t("details.category"), t(`cat.${categoryInfo(task).key}`))}
      ${detailsItem(t("details.health"), health)}
      ${detailsItem(t("details.size"), formatSize(task.total))}
      ${detailsItem(t("details.downloaded"), formatSize(task.downloaded))}
      ${detailsItem(t("details.speed"), `${formatMB(task.speed)} ${t("unit.mbps")}`)}
      ${detailsItem(t("details.eta"), formatETA(task.eta))}
      ${detailsItem(t("details.connections"), formatInteger(task.connections || 0))}
      ${detailsItem(t("details.retries"), formatInteger(task.retries || 0))}
      ${detailsItem(t("details.quality"), task.quality || "best")}
      ${detailsItem(t("details.container"), task.container || fileBadge(task))}
      ${detailsItem(t("details.sha256"), task.sha256, true)}
      ${detailsItem(t("details.md5"), task.md5, true)}
      ${detailsItem(t("details.path"), task.filePath, true)}
    </div>
    ${task.error ? `<div class="details-error">
      <span class="details-error-label">${escapeHTML(t("details.errorCause"))}</span>
      <p>${escapeHTML(errorCause(task))}</p>
      <details class="details-raw">
        <summary>${escapeHTML(t("details.errorRaw"))}</summary>
        <code dir="ltr">${escapeHTML(task.error)}</code>
      </details>
    </div>` : ""}
    <div class="details-actions">
      <button type="button" class="btn btn-ghost btn-small" data-details-open="${escapeHTML(task.id)}">${escapeHTML(t("details.openFile"))}</button>
      ${task.status === "completed" ? `<button type="button" class="btn btn-primary btn-small" data-details-verify="${escapeHTML(task.id)}">${escapeHTML(t("details.verify"))}</button>` : ""}
    </div>`;
}

function openTaskDetails(task) {
  if (!task) return;
  renderTaskDetails(task);
  openDialog(detailsDialog);
}

async function handleTaskAction(action, id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task) return;
  try {
    if (action === "pause") {
      upsertTask(await api().PauseTask(id));
      showToast(t("toast.paused"));
    } else if (action === "resume") {
      upsertTask(await api().ResumeTask(id));
      showToast(t("toast.resumed"));
    } else if (action === "cancel") {
      upsertTask(await api().CancelTask(id));
      showToast(t("toast.canceled"));
    } else if (action === "remove") {
      if (!window.confirm(t("task.confirmRemove"))) return;
      removeTaskFromState(id);
      try {
        await api().RemoveTask(id);
        showToast(t("toast.removed"));
      } catch (error) {
        upsertTask(task);
        throw error;
      }
    } else if (action === "remove-file") {
      if (!window.confirm(t("task.confirmRemoveFile"))) return;
      try {
        await api().DeleteTasks([id], true);
        removeTaskFromState(id);
        showToast(t("toast.removedFile"), "success");
      } catch (error) {
        await syncTasks();
        throw error;
      }
    } else if (action === "open") {
      await api().OpenTaskFile(id);
    } else if (action === "folder") {
      if (typeof api().OpenTaskDir === "function") await api().OpenTaskDir(id);
      else await api().OpenDownloadDir();
    } else if (action === "details") {
      openTaskDetails(task);
    } else if (action === "verify") {
      const updated = await api().VerifyTask(id);
      upsertTask(updated);
      if (detailsDialog.open) renderTaskDetails(updated);
      showToast(t("task.verified"), "success");
    } else if (action === "copy") {
      if (await copyText(task.url)) showToast(t("task.copied"), "success");
      else showToast(t("task.copyError"), "error");
    } else if (action === "queue-up" || action === "queue-down") {
      const direction = action === "queue-up" ? "up" : "down";
      const before = queuedOrder().map((item) => item.id).join("\u0001");
      const ordered = await api().MoveTaskInQueue(id, direction);
      applyQueueOrder(ordered);
      if (before !== (ordered || []).map((item) => item.id).join("\u0001")) {
        showToast(t("toast.queueMoved"), "success");
      }
    }
  } catch (error) {
    showToast(`${t("toast.actionError")} ${error?.message || error || ""}`.trim(), "error");
  }
}

function syncScheduleFields() {
  const enabled = $("#settings-schedule").checked;
  ["#settings-schedule-start", "#settings-schedule-stop"].forEach((selector) => {
    const input = $(selector);
    if (input) input.disabled = !enabled;
  });
}

