let dropDepth = 0;

function dropHasItems(event) {
  const types = Array.from(event.dataTransfer?.types || []);
  return types.includes("Files") || types.includes("text/uri-list");
}

function showDropOverlay() {
  if (!dropOverlay || !hasAPI()) return;
  dropOverlay.hidden = false;
  dropOverlay.setAttribute("aria-hidden", "false");
}

function hideDropOverlay() {
  dropDepth = 0;
  if (!dropOverlay) return;
  dropOverlay.hidden = true;
  dropOverlay.setAttribute("aria-hidden", "true");
}

async function addDroppedTorrents(paths) {
  if (!hasAPI()) {
    showToast(t("app.bootError"), "error");
    return;
  }
  const torrents = paths.filter((path) => /\.torrent$/i.test(String(path)));
  if (!torrents.length) {
    showToast(t("drop.unsupported"), "error");
    return;
  }
  let added = 0;
  for (const path of torrents) {
    try {
      const task = await api().AddTorrentPath(path);
      if (task?.id) {
        upsertTask(task);
        added += 1;
      }
    } catch (error) {
      showToast(`${t("drop.error")} ${error?.message || error || ""}`.trim(), "error");
    }
  }
  if (added) {
    setFilter("all");
    showToast(t("drop.torrent"), "success");
  }
}

async function addDroppedText(text) {
  if (!hasAPI()) {
    showToast(t("app.bootError"), "error");
    return;
  }
  const value = String(text || "")
    .split(/\r?\n/)
    .map((item) => item.trim())
    .find((item) => validateDownloadURL(item));
  if (!value) {
    showToast(t("drop.unsupported"), "error");
    return;
  }
  try {
    const task = await api().AddDownload({ url: value, engine: "auto", quality: "best" });
    upsertTask(task);
    setFilter("all");
    showToast(t("drop.added"), "success");
  } catch (error) {
    showToast(`${t("drop.error")} ${error?.message || error || ""}`.trim(), "error");
  }
}

function wireDropTarget() {
  window.addEventListener("dragenter", (event) => {
    if (!dropHasItems(event)) return;
    event.preventDefault();
    dropDepth += 1;
    showDropOverlay();
  });
  window.addEventListener("dragover", (event) => {
    if (!dropHasItems(event)) return;
    event.preventDefault();
    if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
    showDropOverlay();
  });
  window.addEventListener("dragleave", (event) => {
    if (!dropHasItems(event) && dropDepth === 0) return;
    dropDepth = Math.max(0, dropDepth - 1);
    if (dropDepth === 0) hideDropOverlay();
  });
  window.addEventListener("dragend", hideDropOverlay);
  window.addEventListener("drop", (event) => {
    const types = Array.from(event.dataTransfer?.types || []);
    const text = event.dataTransfer?.getData("text/uri-list") || "";
    if (!types.includes("Files") && !text) return;
    event.preventDefault();
    hideDropOverlay();
    if (types.includes("Files")) return;
    if (text) addDroppedText(text);
  });
}

async function saveSettings(event) {
  event.preventDefault();
  const folder = $("#settings-folder").value.trim();
  if (!folder) {
    settingsFeedback.textContent = t("settings.invalidFolder");
    settingsFeedback.hidden = false;
    return;
  }
  const proxy = $("#settings-proxy").value.trim();
  const scheduleEnabled = $("#settings-schedule").checked;
  const scheduleStart = $("#settings-schedule-start").value;
  const scheduleStop = $("#settings-schedule-stop").value;
  if (scheduleEnabled && (!/^([01]\d|2[0-3]):[0-5]\d$/.test(scheduleStart) || !/^([01]\d|2[0-3]):[0-5]\d$/.test(scheduleStop))) {
    settingsFeedback.textContent = t("settings.scheduleError");
    settingsFeedback.hidden = false;
    return;
  }
  if (scheduleEnabled && scheduleStart === scheduleStop) {
    settingsFeedback.textContent = t("settings.scheduleEqual");
    settingsFeedback.hidden = false;
    return;
  }
  if (proxy && !/^(https?|socks[45]?):\/\/.+:\d+/.test(proxy) && !/^[^/]+:\d+$/.test(proxy)) {
    settingsFeedback.textContent = t("settings.proxyError");
    settingsFeedback.hidden = false;
    return;
  }
  const settings = {
    ...state.settings,
    downloadDir: folder,
    maxConcurrent: Math.max(1, Math.min(8, Number($("#settings-concurrent").value) || 2)),
    connections: Math.max(1, Math.min(16, Number($("#settings-connections").value) || 8)),
    proxy,
    clipboardWatch: $("#settings-clipboard").checked,
    autoAddClipboard: $("#settings-auto-clipboard").checked,
    autoStart: $("#settings-autostart").checked,
    autoRetry: $("#settings-autoretry").checked,
    shutdownOnComplete: $("#settings-shutdown").checked,
    notifyOnComplete: $("#settings-notify").checked,
    browserBridgeEnabled: $("#settings-bridge").checked,
    browserToken: $("#settings-bridge-token").value.trim(),
    scheduleEnabled,
    scheduleStart: scheduleEnabled ? scheduleStart : "",
    scheduleStop: scheduleEnabled ? scheduleStop : "",
    githubToken: $("#settings-token").value.trim()
  };
  try {
    state.settings = await api().SaveSettings(settings);
    $("#settings-bridge-token").value = state.settings.browserToken || "";
    accent = $("#settings-accent").value;
    storage.set("dm-accent", accent);
    applyAccent(accent);
    refreshBridgeInfo();
    closeDialog(settingsDialog);
    showToast(t("settings.saved"), "success");
  } catch (error) {
    settingsFeedback.textContent = `${t("settings.saveError")} ${error?.message || error || ""}`.trim();
    settingsFeedback.hidden = false;
  }
}

