function githubErrorText(error) {
  const message = String(error?.message || error || "");
  if (/rate limit|too many requests|\(429\)/i.test(message)) return t("github.rateLimit");
  if (/bad credentials|\(401\)/i.test(message)) return `${t("github.badToken")} ${message}`.trim();
  if (/validation failed|\(422\)/i.test(message)) return `${t("github.validation")} ${message}`.trim();
  return `${t("github.error")} ${message}`.trim();
}

let githubRequest = 0;

async function searchGitHub(event) {
  event.preventDefault();
  const query = $("#github-query").value.trim();
  if (query.length < 2) return;
  const request = ++githubRequest;
  githubFeedback.hidden = true;
  githubResults.innerHTML = `<p class="github-hint">${escapeHTML(t("github.loading"))}</p>`;
  try {
    const repos = await api().SearchGitHub(query);
    if (request !== githubRequest) return;
    if (!repos.length) {
      githubResults.innerHTML = `<p class="github-hint">${escapeHTML(t("github.noResults"))}</p>`;
      return;
    }
    githubResults.innerHTML = repos.map((repo) => `<article class="repo-card">
      <div class="repo-main">
        <strong>${escapeHTML(repo.fullName)}</strong>
        <p>${escapeHTML(repo.description || "")}</p>
        <span class="repo-meta">${formatInteger(repo.stars || 0)} ${escapeHTML(t("github.stars"))}${repo.language ? ` · ${escapeHTML(repo.language)}` : ""}</span>
      </div>
      <div class="repo-actions">
        <button type="button" class="btn btn-primary btn-small" data-gh-repo="${escapeHTML(repo.owner)}" data-gh-name="${escapeHTML(repo.name)}" data-gh-branch="${escapeHTML(repo.defaultBranch || "main")}" data-gh-title="${escapeHTML(repo.name)}">${escapeHTML(t("github.zip"))}</button>
        <button type="button" class="btn btn-ghost btn-small" data-gh-releases="${escapeHTML(repo.owner)}" data-gh-repo-name="${escapeHTML(repo.name)}">${escapeHTML(t("github.releases"))}</button>
        <button type="button" class="icon-btn" data-gh-open="${escapeHTML(repo.htmlUrl)}" aria-label="${escapeHTML(t("github.open"))}" title="${escapeHTML(t("github.open"))}"><svg class="icon" aria-hidden="true"><use href="#i-github"></use></svg></button>
      </div>
    </article>`).join("");
  } catch (error) {
    if (request !== githubRequest) return;
    githubFeedback.textContent = githubErrorText(error);
    githubFeedback.hidden = false;
    githubResults.innerHTML = "";
  }
}

async function loadReleases(owner, repo) {
  const request = ++githubRequest;
  githubFeedback.hidden = true;
  githubResults.innerHTML = `<p class="github-hint">${escapeHTML(t("github.loading"))}</p>`;
  try {
    const releases = await api().GetGitHubReleases(owner, repo);
    if (request !== githubRequest) return;
    if (!releases.length) {
      githubResults.innerHTML = `<p class="github-hint">${escapeHTML(t("github.noReleases"))}</p>`;
      return;
    }
    githubResults.innerHTML = releases.map((release) => `<section class="release-block">
      <div class="release-head"><strong>${escapeHTML(release.name || release.tag)}</strong><span>${escapeHTML(release.tag)}</span><button type="button" class="btn btn-ghost btn-small" data-gh-tag-owner="${escapeHTML(owner)}" data-gh-tag-repo="${escapeHTML(repo)}" data-gh-tag-name="${escapeHTML(release.tag)}" data-gh-tag-title="${escapeHTML(repo + "-" + release.tag)}">${escapeHTML(t("github.tagZip"))}</button></div>
      ${release.assets?.length ? `<div class="asset-list">${release.assets.map((asset) => `<button type="button" class="asset-btn" data-gh-asset="${escapeHTML(JSON.stringify(asset))}" data-gh-asset-repo="${escapeHTML(owner + "/" + repo)}" data-gh-asset-tag="${escapeHTML(release.tag)}"><span>${escapeHTML(asset.name)}</span><small>${escapeHTML(formatSize(asset.size))}</small></button>`).join("")}</div>` : `<p class="github-hint">${escapeHTML(t("github.noAssets"))}</p>`}
    </section>`).join("");
  } catch (error) {
    if (request !== githubRequest) return;
    githubFeedback.textContent = githubErrorText(error);
    githubFeedback.hidden = false;
  }
}

