const TEXT_FIELD_TYPES = new Set(["", "text", "search", "url", "email", "tel", "password", "number"]);
const fieldMenu = $("#field-menu");
let fieldMenuTarget = null;

function isTextField(element) {
  if (!(element instanceof HTMLElement)) return false;
  if (element.tagName === "TEXTAREA") return !element.disabled && !element.readOnly;
  return element.tagName === "INPUT" && TEXT_FIELD_TYPES.has(element.type) && !element.disabled && !element.readOnly;
}

function fieldSelection(field) {
  const start = field.selectionStart ?? field.value.length;
  const end = field.selectionEnd ?? start;
  return { start, end, text: end > start ? field.value.slice(start, end) : "" };
}

function closeFieldMenu(restoreFocus = false) {
  if (!fieldMenu || fieldMenu.hidden) return;
  const target = fieldMenuTarget;
  fieldMenu.hidden = true;
  fieldMenuTarget = null;
  if (restoreFocus && target) target.focus();
}

function positionFieldMenu(x, y) {
  const pad = 8;
  const rect = fieldMenu.getBoundingClientRect();
  fieldMenu.style.left = `${Math.max(pad, Math.min(x, window.innerWidth - rect.width - pad))}px`;
  const top = y + rect.height + pad > window.innerHeight ? y - rect.height : y;
  fieldMenu.style.top = `${Math.max(pad, top)}px`;
}

function showFieldMenu(field, x, y) {
  if (!isTextField(field)) return;
  fieldMenuTarget = field;
  const { text } = fieldSelection(field);
  const hideClipboard = field.type === "password";
  fieldMenu.querySelector('[data-field-action="cut"]').disabled = hideClipboard || !text;
  fieldMenu.querySelector('[data-field-action="copy"]').disabled = hideClipboard || !text;
  fieldMenu.querySelector('[data-field-action="paste"]').disabled = false;
  fieldMenu.querySelector('[data-field-action="selectAll"]').disabled = false;
  const host = field.closest("dialog[open]") || document.body;
  if (fieldMenu.parentElement !== host) host.appendChild(fieldMenu);
  fieldMenu.hidden = false;
  fieldMenu.style.left = "-9999px";
  fieldMenu.style.top = "-9999px";
  positionFieldMenu(x, y);
  fieldMenu.querySelector("button:not(:disabled)")?.focus();
}

async function readClipboardText() {
  try {
    if (window.runtime?.ClipboardGetText) {
      const text = await window.runtime.ClipboardGetText();
      if (typeof text === "string") return text;
    }
  } catch {
    // fall through to the browser API
  }
  try {
    return await navigator.clipboard.readText();
  } catch {
    return "";
  }
}

function replaceFieldSelection(field, text) {
  if (!text) return;
  field.focus();
  if (field.type === "number") {
    field.value = text;
  } else {
    const { start, end } = fieldSelection(field);
    field.setRangeText(text, start, end, "end");
  }
  field.dispatchEvent(new Event("input", { bubbles: true }));
}

async function runFieldAction(action, field) {
  if (!field) return;
  const { start, end, text } = fieldSelection(field);
  if (action === "selectAll") {
    field.focus();
    field.select();
    return;
  }
  if (action === "copy" || action === "cut") {
    if (!text || !(await copyText(text))) return;
    if (action === "cut") {
      field.focus();
      field.setRangeText("", start, end, "end");
      field.dispatchEvent(new Event("input", { bubbles: true }));
    }
    return;
  }
  if (action === "paste") {
    replaceFieldSelection(field, await readClipboardText());
  }
}

function bindFieldMenu() {
  if (!fieldMenu) return;
  document.addEventListener("contextmenu", (event) => {
    const field = event.target.closest("input, textarea");
    if (!isTextField(field)) return;
    event.preventDefault();
    event.stopPropagation();
    showFieldMenu(field, event.clientX, event.clientY);
  }, true);
  document.addEventListener("mousedown", async (event) => {
    if (event.button !== 1) return;
    const field = event.target.closest("input, textarea");
    if (!isTextField(field)) return;
    event.preventDefault();
    replaceFieldSelection(field, await readClipboardText());
  }, true);
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !fieldMenu.hidden) {
      event.preventDefault();
      closeFieldMenu(true);
      return;
    }
    if ((event.key === "ContextMenu" || (event.shiftKey && event.key === "F10")) && isTextField(document.activeElement)) {
      event.preventDefault();
      const rect = document.activeElement.getBoundingClientRect();
      showFieldMenu(document.activeElement, rect.left + 12, rect.bottom + 4);
    }
  });
  fieldMenu.addEventListener("click", async (event) => {
    const button = event.target.closest("[data-field-action]");
    if (!button) return;
    const field = fieldMenuTarget;
    closeFieldMenu();
    await runFieldAction(button.dataset.fieldAction, field);
    field?.focus();
  });
  document.addEventListener("pointerdown", (event) => {
    if (!fieldMenu.hidden && !event.target.closest("#field-menu")) closeFieldMenu();
  }, true);
  document.addEventListener("scroll", () => closeFieldMenu(), true);
  window.addEventListener("blur", closeFieldMenu);
  window.addEventListener("resize", closeFieldMenu);
}

function bindEvents() {
  bindFieldMenu();
  themeToggle.addEventListener("click", () => {
    theme = theme === "light" ? "dark" : "light";
    storage.set("dm-theme", theme);
    applyTheme();
    prefsStatus.textContent = t(theme === "dark" ? "prefs.themeDark" : "prefs.themeLight");
  });
  languageToggle.addEventListener("click", () => {
    const nextLang = lang === "fa" ? "en" : "fa";
    storage.set("dm-lang", nextLang);
    applyLanguage(nextLang);
    prefsStatus.textContent = t("prefs.langChanged");
  });
  searchForm.addEventListener("submit", (event) => event.preventDefault());
  searchInput.addEventListener("input", () => {
    state.query = searchInput.value;
    renderTasks();
  });
  $$(".filter").forEach((button) => {
    button.addEventListener("click", () => {
      state.category = "all";
      $$(".side-link[data-category]").forEach((item) => item.classList.remove("is-active"));
      setFilter(button.dataset.filter);
    });
  });
  $$(".side-link[data-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.category = "all";
      $$(".side-link[data-category]").forEach((item) => item.classList.remove("is-active"));
      setFilter(button.dataset.filter);
    });
  });
  $$(".side-link[data-category]").forEach((button) => {
    button.addEventListener("click", () => setCategory(button.dataset.category));
  });
  $$("[data-open-download]").forEach((button) => button.addEventListener("click", () => openDownloadDialog()));
  $("#settings-header").addEventListener("click", openSettingsDialog);
  $("#github-entry").addEventListener("click", openGitHubDialog);
  if (pauseAllButton) pauseAllButton.addEventListener("click", pauseAll);
  if (resumeAllButton) resumeAllButton.addEventListener("click", resumeAll);
  if (sortToggle) sortToggle.addEventListener("click", cycleSort);
  if (selectAll) selectAll.addEventListener("change", () => setVisibleSelected(selectAll.checked));
  if (selectAllToggle) {
    selectAllToggle.addEventListener("click", () => {
      const visible = visibleTaskList();
      const allSelected = visible.length > 0 && visible.every((task) => state.selected.has(task.id));
      setVisibleSelected(!allSelected);
    });
  }
  if (bulkBar) {
    bulkBar.addEventListener("click", (event) => {
      const button = event.target.closest("[data-bulk]");
      if (button) bulkAction(button.dataset.bulk);
    });
  }
  $$(".speed-period").forEach((button) => {
    button.addEventListener("click", () => selectChartPeriod(button.dataset.period));
  });
  downloadsBody.addEventListener("change", (event) => {
    const box = event.target.closest("[data-select]");
    if (!box) return;
    if (box.checked) state.selected.add(box.dataset.select);
    else state.selected.delete(box.dataset.select);
    renderSelectionUI();
  });
  retryButton.addEventListener("click", async () => {
    await boot(true);
    downloadsTitle.setAttribute("tabindex", "-1");
    downloadsTitle.focus({ preventScroll: true });
  });
  emptyAction.addEventListener("click", () => {
    if (emptyAction.dataset.action === "new") openDownloadDialog();
    else resetFilters();
  });
  downloadsBody.addEventListener("click", (event) => {
    const button = event.target.closest("[data-action]");
    if (button) {
      handleTaskAction(button.dataset.action, button.dataset.id);
      return;
    }
    const summary = event.target.closest(".row-menu > summary");
    if (!summary) return;
    const menu = summary.parentElement;
    requestAnimationFrame(() => {
      if (!menu.open) return;
      menu.classList.remove("menu-up");
      const panel = menu.querySelector(".menu-panel");
      if (panel && panel.getBoundingClientRect().bottom > window.innerHeight - 10) {
        menu.classList.add("menu-up");
      }
    });
  });
  document.addEventListener("click", (event) => {
    if (event.target.closest(".row-menu")) return;
    $$(".row-menu[open]").forEach((menu) => menu.removeAttribute("open"));
  });

  $("#close-dialog").addEventListener("click", () => closeDialog(downloadDialog));
  $("#cancel-dialog").addEventListener("click", () => closeDialog(downloadDialog));
  $("#pick-torrent").addEventListener("click", pickTorrent);
  $("#open-github").addEventListener("click", () => {
    closeDialog(downloadDialog);
    openGitHubDialog();
  });
  $("#gh-token-help").addEventListener("click", () => {
    if (hasAPI()) api().OpenExternal("https://github.com/settings/tokens");
  });
  $("#gh-token-form").addEventListener("submit", async (event) => {
    event.preventDefault();
    const input = $("#gh-token-input");
    const token = input.value.trim();
    if (!token || !hasAPI()) return;
    if (!state.settings) {
      showToast(t("app.bootError"), "error");
      return;
    }
    try {
      state.settings = await api().SaveSettings({ ...state.settings, githubToken: token });
      input.value = "";
      $("#gh-token").removeAttribute("open");
      showToast(t("github.tokenSaved"));
    } catch (error) {
      showToast(`${t("toast.actionError")} ${error?.message || error || ""}`.trim(), "error");
    }
  });
  downloadForm.addEventListener("submit", submitDownload);
  urlInput.addEventListener("input", () => {
    urlError.hidden = true;
    feedback.hidden = true;
    urlInput.removeAttribute("aria-invalid");
    syncDownloadFields();
  });
  downloadEngine.addEventListener("change", syncDownloadFields);
  downloadQuality.addEventListener("change", () => {
    if (downloadQuality.value === "audio") downloadContainer.value = "mp3";
    syncDownloadFields();
  });
  downloadContainer.addEventListener("change", () => {
    if (downloadContainer.value === "mp3") downloadQuality.value = "audio";
    syncDownloadFields();
  });
  downloadDialog.addEventListener("close", () => {
    document.body.classList.remove("dialog-open");
    downloadForm.reset();
    downloadEngine.value = "auto";
    downloadCategory.value = "";
    syncDownloadFields();
    urlError.hidden = true;
    feedback.hidden = true;
    urlInput.removeAttribute("aria-invalid");
  });

  $("#close-settings").addEventListener("click", () => closeDialog(settingsDialog));
  $("#cancel-settings").addEventListener("click", () => closeDialog(settingsDialog));
  $("#choose-folder").addEventListener("click", chooseFolder);
  $("#copy-bridge-token").addEventListener("click", copyBridgeToken);
  $("#open-extension").addEventListener("click", openExtensionFolder);
  palettePresets.addEventListener("click", (event) => {
    const button = event.target.closest("[data-palette]");
    if (button) setPalette(button.dataset.palette);
  });
  $("#settings-accent").addEventListener("input", (event) => {
    accent = event.target.value;
    applyAccent(accent);
  });
  $$(".theme-option").forEach((button) => {
    button.addEventListener("click", () => {
      theme = button.dataset.themeChoice === "light" ? "light" : "dark";
      storage.set("dm-theme", theme);
      applyTheme();
    });
  });
  $("#reset-accent").addEventListener("click", () => {
    accent = "";
    storage.set("dm-accent", "");
    applyAccent("");
    $("#settings-accent").value = paletteAccent();
  });
  $("#open-tools").addEventListener("click", () => api()?.OpenToolsFolder().catch(() => showToast(t("toast.actionError"), "error")));
  settingsForm.addEventListener("submit", saveSettings);
  $("#settings-schedule").addEventListener("change", syncScheduleFields);
  settingsDialog.addEventListener("close", () => document.body.classList.remove("dialog-open"));

  $("#close-github").addEventListener("click", () => closeDialog(githubDialog));
  $("#github-search-form").addEventListener("submit", searchGitHub);
  githubDialog.addEventListener("close", () => document.body.classList.remove("dialog-open"));
  $("#close-details").addEventListener("click", () => closeDialog(detailsDialog));
  detailsDialog.addEventListener("close", () => document.body.classList.remove("dialog-open"));
  detailsBody.addEventListener("click", async (event) => {
    const openButton = event.target.closest("[data-details-open]");
    if (openButton) {
      api()?.OpenTaskFile(openButton.dataset.detailsOpen).catch(() => showToast(t("toast.actionError"), "error"));
      return;
    }
    const verifyButton = event.target.closest("[data-details-verify]");
    if (verifyButton) {
      await handleTaskAction("verify", verifyButton.dataset.detailsVerify);
    }
  });
  githubResults.addEventListener("click", (event) => {
    const tagButton = event.target.closest("[data-gh-tag-owner]");
    if (tagButton) {
      downloadTag(tagButton.dataset.ghTagOwner, tagButton.dataset.ghTagRepo, tagButton.dataset.ghTagName, tagButton.dataset.ghTagTitle || "");
      return;
    }
    const repoButton = event.target.closest("[data-gh-repo]");
    if (repoButton) {
      downloadRepo(repoButton.dataset.ghRepo, repoButton.dataset.ghName, repoButton.dataset.ghBranch || "main", repoButton.dataset.ghTitle || "");
      return;
    }
    const releaseButton = event.target.closest("[data-gh-releases]");
    if (releaseButton) {
      loadReleases(releaseButton.dataset.ghReleases, releaseButton.dataset.ghRepoName);
      return;
    }
    const assetButton = event.target.closest("[data-gh-asset]");
    if (assetButton) {
      downloadAsset(assetButton.dataset.ghAsset, assetButton.dataset.ghAssetRepo, assetButton.dataset.ghAssetTag);
      return;
    }
    const openButton = event.target.closest("[data-gh-open]");
    if (openButton) api()?.OpenExternal(openButton.dataset.ghOpen);
  });

  $$("dialog").forEach((dialog) => {
    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) closeDialog(dialog);
    });
  });

  const clipboardBanner = $("#clipboard-banner");
  $("#clipboard-add").addEventListener("click", async () => {
    if (!state.clipboardURL) return;
    try {
      const task = await api().AddDownload({ url: state.clipboardURL, engine: "auto", quality: "best" });
      upsertTask(task);
      showToast(t("toast.clipboard"), "success");
      clipboardBanner.hidden = true;
      state.clipboardURL = "";
      setFilter("all");
    } catch (error) {
      showToast(`${t("toast.actionError")} ${error?.message || error || ""}`.trim(), "error");
    }
  });
  $("#clipboard-dismiss").addEventListener("click", () => {
    clipboardBanner.hidden = true;
    state.clipboardURL = "";
  });

  const navLinks = $$(".main-nav a, .bottom-nav a");
  navLinks.forEach((link) => {
    link.addEventListener("click", () => {
      const target = link.getAttribute("href");
      navLinks.forEach((item) => {
        const current = item.getAttribute("href") === target;
        item.classList.toggle("is-active", current);
        if (current) item.setAttribute("aria-current", "true");
        else item.removeAttribute("aria-current");
      });
    });
  });
}

function wireWailsEvents() {
  const runtime = window.runtime;
  if (!runtime?.EventsOn) return;
  runtime.EventsOn("task:update", (task) => upsertTask(task));
  runtime.EventsOn("task:removed", (payload) => removeTaskFromState(payload?.id));
  runtime.EventsOn("stats:update", (stats) => {
    state.stats = stats;
    pushSpeedSample(stats?.speed || 0);
    scheduleRender("stats");
  });
  runtime.EventsOn("settings:update", (settings) => { state.settings = settings; });
  runtime.EventsOn("schedule:update", (payload) => {
    showToast(payload?.paused ? t("toast.schedulePaused") : t("toast.scheduleResumed"));
  });
  runtime.EventsOn("shutdown:notify", () => {
    showToast(t("toast.shutdownPlanned"));
  });
  runtime.EventsOn("toast", (payload) => {
    if (payload?.message) showToast(payload.message, payload.kind || "info");
  });
  runtime.EventsOn("clipboard:added", () => {
    showToast(t("toast.clipboard"), "success");
  });
  runtime.EventsOn("clipboard:url", async (payload) => {
    const url = String(payload?.url || "").trim();
    if (!url) return;
    state.clipboardURL = url;
    $("#clipboard-url").textContent = url;
    $("#clipboard-banner").hidden = false;
    if (state.settings?.autoAddClipboard) {
      window.setTimeout(() => { $("#clipboard-banner").hidden = true; }, 1200);
    }
  });
  if (runtime.OnFileDrop) {
    runtime.OnFileDrop((x, y, paths) => {
      hideDropOverlay();
      addDroppedTorrents(paths || []);
    }, false);
  }
}

async function boot(isRetry = false) {
  if (!hasAPI()) {
    state.booted = true;
    downloadsTable.hidden = true;
    tablePanel.hidden = false;
    stateLoading.hidden = true;
    stateEmpty.hidden = true;
    stateError.hidden = false;
    const errorText = stateError.querySelector("p");
    if (errorText) errorText.textContent = t("app.bootError");
    if (pageSub) pageSub.textContent = t("app.bootError");
    return;
  }
  if (!isRetry) {
    state.booted = false;
    renderTasks();
  }
  try {
    const initial = await api().GetInitialState();
    if (initial.error) throw new Error(initial.error);
    state.settings = initial.settings || {};
    state.tasks = initial.tasks || [];
    state.stats = initial.stats || state.stats;
    state.speedHistory = initial.speedHistory || [];
    state.tools = initial.tools || {};
    state.booted = true;
    pushSpeedSample(state.stats?.speed || 0);
    renderAll();
    refreshTools();
  } catch (error) {
    state.booted = true;
    tablePanel.hidden = false;
    stateError.hidden = false;
    stateLoading.hidden = true;
    stateEmpty.hidden = true;
    downloadsTable.hidden = true;
    const errorText = stateError.querySelector("p");
    if (errorText) errorText.textContent = `${t("state.errorText")} ${error?.message || error || ""}`.trim();
    showToast(t("app.loadError"), "error");
  }
}

function init() {
  state.sort = storage.get("dm-sort") || "recent";
  bindEvents();
  applyTheme();
  renderConnectionStatus();
  window.addEventListener("online", renderConnectionStatus);
  window.addEventListener("offline", renderConnectionStatus);
  applyLanguage(lang);
  updateSortLabel();
  wireDropTarget();
  wireWailsEvents();
  boot();
}

init();
